import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { ALL_SAREES, ALL_STATE_METAS } from '../src/data/collections/registry';

function escapeSql(val: unknown): string {
  if (val === null || val === undefined) return 'NULL';
  if (typeof val === 'number') return String(val);
  return `'${String(val).replace(/'/g, "''")}'`;
}

export function generateSeedSql(): string {
  const lines: string[] = [
    '-- Idempotent DRIFT Commerce Seed Data',
    '-- Autogenerated from src/data/collections',
    '',
  ];

  // States
  lines.push('-- STATES');
  ALL_STATE_METAS.forEach((state, idx) => {
    const slug = escapeSql(state.slug);
    const name = escapeSql(state.name);
    const tagline = escapeSql(state.tagline);
    const craftHistory = escapeSql(state.craftOverview);
    const heroImage = escapeSql(state.heroImage);
    const accentHex = escapeSql(state.accentColor);
    const displayOrder = idx + 1;

    lines.push(
      `INSERT OR REPLACE INTO states (slug, name, tagline, craft_history, hero_image, accent_hex, display_order) ` +
        `VALUES (${slug}, ${name}, ${tagline}, ${craftHistory}, ${heroImage}, ${accentHex}, ${displayOrder});`
    );
  });

  lines.push('');
  lines.push('-- SAREES');

  ALL_SAREES.forEach((saree, idx) => {
    const id = escapeSql(saree.id);
    const sku = escapeSql(saree.slug ? `DRIFT-${saree.slug.toUpperCase().slice(0, 24)}` : `DRIFT-SKU-${idx + 100}`);
    const title = escapeSql(saree.title || saree.name);
    const stateSlug = escapeSql(saree.region);
    const craftOrigin = escapeSql(saree.provenance || saree.originState);
    const weaveType = escapeSql(saree.craft);
    const fabric = escapeSql(saree.fabric);
    const priceInr = Number(saree.price) || 45000;
    const originalPriceInr = Number(saree.originalPrice) || Math.round(priceInr * 1.2);
    const badge = escapeSql(saree.trendingBadge || 'Design Study');

    const colors = Array.from(new Set([saree.colorHex, ...(saree.palette || [])].filter(Boolean)));
    const colorsJson = escapeSql(JSON.stringify(colors.length > 0 ? colors : ['#A80F24', '#D4AF37']));
    const blouseSizesJson = escapeSql(JSON.stringify(['Unstitched', '34 (XS)', '36 (S)', '38 (M)', '40 (L)', '42 (XL)']));
    const culturalStory = escapeSql(saree.story || saree.description);
    const primaryImage = escapeSql(saree.images.primary);
    const hoverImage = escapeSql(saree.images.detail || saree.images.primary);

    const isBridal =
      saree.title.toLowerCase().includes('bridal') ||
      saree.description.toLowerCase().includes('bridal') ||
      saree.slug.includes('bridal') ||
      idx % 6 === 0
        ? 1
        : 0;

    const isFeaturedArc = idx % 8 === 0 ? 1 : 0;
    const occasionTag = escapeSql(saree.drapeStyle || 'Festive & Royal Occasion');
    const stockCount = saree.stockCount || 25;

    lines.push(
      `INSERT OR REPLACE INTO sarees (id, sku, title, state_slug, craft_origin, weave_type, fabric, price_inr, original_price_inr, badge, colors_json, blouse_sizes_json, cultural_story, primary_image, hover_image, is_bridal, is_featured_arc, occasion_tag, stock_count) ` +
        `VALUES (${id}, ${sku}, ${title}, ${stateSlug}, ${craftOrigin}, ${weaveType}, ${fabric}, ${priceInr}, ${originalPriceInr}, ${badge}, ${colorsJson}, ${blouseSizesJson}, ${culturalStory}, ${primaryImage}, ${hoverImage}, ${isBridal}, ${isFeaturedArc}, ${occasionTag}, ${stockCount});`
    );
  });

  return lines.join('\n');
}

async function run() {
  const seedSql = generateSeedSql();
  const outPath = path.resolve(process.cwd(), 'db', 'seed.sql');
  fs.writeFileSync(outPath, seedSql, 'utf-8');
  console.log(`[SEED] Generated ${outPath} (${ALL_STATE_METAS.length} states, ${ALL_SAREES.length} sarees).`);

  const isRemote = process.argv.includes('--remote');
  const targetFlag = isRemote ? '--remote' : '--local';
  console.log(`[SEED] Executing against D1 (${targetFlag})...`);

  try {
    execSync(`npx wrangler d1 execute drift-commerce-db ${targetFlag} --file=./db/seed.sql`, {
      stdio: 'inherit',
    });
    console.log('[SEED] D1 seeding completed successfully.');
  } catch (err) {
    console.warn('[SEED] Note: wrangler d1 execute returned:', (err as Error).message);
  }
}

if (require.main === module || process.argv[1]?.endsWith('seed.ts')) {
  run();
}
